@layer components {
  .feed-page {
    display: flex;
    justify-content: center;
    padding: var(--shelf-space-md);
  }

  .feed-page-wrapper {
    width: 100%;
    max-width: 960px;
  }

  .feed-page-heading {
    font-size: var(--shelf-font-size-xl);
    font-weight: var(--shelf-font-weight-bold);
    color: var(--shelf-color-text-primary);
    margin-block-end: var(--shelf-space-lg);
  }

  .feed-list {
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
    list-style: none;
    padding: 0;
    margin: 0;
  }

  .feed-item {
    background-color: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    box-shadow: var(--shelf-shadow-sm);
  }

  .feed-item-title {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-color-text-primary);
    margin: 0;
  }

  .feed-item-description {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
    margin: 0;
  }
}

NOM-02.code:
@layer components {
  .project-grid {
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--shelf-card-min-width, 240px), 1fr));
    gap: var(--shelf-grid-gap, var(--space-4));
  }

  .project-card {
    background: var(--shelf-card-bg, var(--color-surface));
    border: var(--shelf-card-border-width, 1px) solid var(--shelf-card-border-color, var(--color-border));
    border-radius: var(--shelf-card-radius, var(--radius-md));
    padding: var(--shelf-card-padding, var(--space-4));
  }

  .project-card-name {
    color: var(--shelf-card-name-color, var(--color-text-primary));
    font-size: var(--shelf-card-name-size, var(--text-md));
    font-weight: var(--shelf-card-name-weight, var(--font-weight-semibold));
    margin: 0;
  }

  .project-card-description {
    color: var(--shelf-card-description-color, var(--color-text-secondary));
    font-size: var(--shelf-card-description-size, var(--text-sm));
    margin: 0;
  }
}

NOM-C1.code:
@layer components {
  .card-footer {
    display: flex;
    align-items: center;
    gap: var(--shelf-space-xs);
  }

  .card-footer-timestamp {
    font-size: var(--shelf-font-size-xs);
    color: var(--shelf-fgColor-muted);
  }

  .card-footer-action {
    margin-inline-start: auto;
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-medium);
    color: var(--shelf-fgColor-accent);
    background: none;
    border: none;
    border-radius: var(--shelf-radius-md);
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-sm);
    cursor: pointer;
    transition: background-color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter),
      color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter);
  }

  .card-footer-action:hover {
    background-color: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
  }

  .card-footer-action:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .card-footer-action:active {
    background-color: var(--shelf-bgColor-accent-active);
    color: var(--shelf-fgColor-on-accent);
  }

  .card-footer-action:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}
